const won = rs.filter((r) => r.s === 201), lost = rs.filter((r) => r.d && r.d.code === 'sold_out'); rec('race: 12 simultaneous guests / 3 seats -> exactly 3 holds, 9 sold_out', won.length === 3 && lost.length === 9, { won: won.length, lost: lost.length, other: rs.filter((r) => r.s !== 201 && !(r.d && r.d.code === 'sold_out')).map((r) => r.s) });
