  rec('confirm: SQL failure at every position leaves the hold unconfirmed', cclean && cn >= 2, { positions: cn }); void beforeC;
  const lost2 = await api('POST', `/preview/admin/bula/holds/${hid}/confirm`, { staff: T.ops, body: { evidence_note: 'acc' }, h: { ...HX, 'x-bula-drop-response': 'on' } }); const st1 = (await myHolds(t)).find((h) => h.holdId === hid).state;
